#!/usr/bin/env bash
docker compose -f backend/docker-compose.yml exec -T backend python -c 'import os,json,urllib.request,re; r=os.environ.get("BASE_RPC_URL",""); c=os.environ.get("BASE_ANCHOR_CONTRACT",""); print("Contract length:",len(c)); print("Contract format:",bool(re.fullmatch(r"0x[0-9a-fA-F]{40}",c))); q=lambda m,p: json.loads(urllib.request.urlopen(urllib.request.Request(r,data=json.dumps({"jsonrpc":"2.0","id":1,"method":m,"params":p}).encode(),headers={"Content-Type":"application/json"}),timeout=10).read()).get("result"); print("Chain ID:",q("eth_chainId",[])); code=q("eth_getCode",[c,"latest"]) if c else None; print("Bytecode:","present" if code not in (None,"0x","0x0") else "missing"); getter="0x"+__import__("eth_hash.auto",fromlist=["keccak"]).keccak(b"anchoredAt(bytes32)")[:4].hex()+"00"*32; result=q("eth_call",[{"to":c,"data":getter},"latest"]) if c else None; print("ScarAnchor interface:","present" if isinstance(result,str) and len(result)>=66 else "missing")'
